<?php
require_once __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require_once __DIR__.'/learning_sharing_fixture.php';$f=learningSharingFixture($db,$f);
require_once __DIR__.'/../includes/exam_paper_service.php';
$owner=learningActor($db,$f['ids']['teacher']);$student=learningActor($db,$f['ids']['student_login']);
$a=curriculumEnsureChapter($db,1,$f['class'],$f['subject'],'Chapter A');
$b=curriculumEnsureChapter($db,1,$f['class'],$f['subject'],'Chapter B');
$t1=curriculumEnsureTopic($db,1,$a,'First topic');$t2=curriculumEnsureTopic($db,1,$a,'Second topic');
$tb=curriculumEnsureTopic($db,1,$b,'Other chapter topic');
$common=['class_id'=>$f['class'],'subject_id'=>$f['subject'],'chapter'=>'Chapter A','difficulty'=>'Easy','required_minutes'=>'2.25','visibility'=>'public','cognitive_domain'=>'Knowledge'];
$short=learningSaveQuestion($db,$owner,$common+['topic_id'=>$t1,'type'=>'Short','marks'=>'2.25','question_text'=>'Short item'],null,'exam');
$long=learningSaveQuestion($db,$owner,$common+['topic_id'=>$t2,'type'=>'Long','marks'=>'3.5','question_text'=>'Long item'],null,'exam');
$mcq=learningSaveQuestion($db,$owner,$common+['topic_id'=>$t1,'type'=>'MCQ','marks'=>'1','question_text'=>'MCQ item','option_a'=>'1','option_b'=>'2','option_c'=>'3','option_d'=>'4','correct_option'=>'A'],null,'exam');
$bq=learningSaveQuestion($db,$owner,array_replace($common,['chapter'=>'Chapter B','topic_id'=>$tb,'type'=>'Very Short','marks'=>1,'question_text'=>'Second chapter item']),null,'exam');
$input=['generation_kind'=>'written','duration_minutes'=>30,'chapters'=>[$a=>['count'=>2,'marks'=>'5.75'],$b=>['count'=>0,'marks'=>999]]];
$paper=examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$input);
erpEqual($paper['total_units'],575,'Simple mode keeps exact decimal marks');
erpEqual(count($paper['questions']),2,'Simple mode exact question count');
erpEqual(array_diff(array_column($paper['questions'],'id'),[$short,$long]),[],'Written mode combines written types, excludes MCQs');
erpEqual($paper['chapter_counts'],['Chapter A'=>2],'Zero count excludes chapter even with marks');
erpEqual($paper['required_units'],450,'Question time is retained');
$multiple=$input;$multiple['chapters'][$b]=['count'=>1,'marks'=>1];
erpEqual(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$multiple)['total_units'],675,'Multiple chapter allocations summed');
$topic=$input;$topic['chapters'][$a]=['count'=>1,'marks'=>'3.5','topic_ids'=>[$t2]];
erpEqual(array_column(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$topic)['questions'],'id'),[$long],'Chapter-wide exact marks choose the matching question');
$bad=$topic;$bad['chapters'][$a]['topic_ids']=[$t1];erpEqual(array_column(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad)['questions'],'id'),[$long],'Legacy exam topic constraints are ignored');
$bad=$topic;$bad['chapters'][$a]['topic_ids']=[$tb];erpEqual(count(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad)['questions']),1,'Old topic IDs cannot restrict chapter-wide exam selection');
$bad=$input;$bad['chapters'][$b]['topic_ids']=[$t1];erpEqual(count(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad)['questions']),2,'Zero-count chapter topics have no effect');
$bad=$input;$bad['chapters'][999999]=['count'=>0];erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'Foreign zero-count chapter rejected');
$mcqInput=['generation_kind'=>'mcq','duration_minutes'=>10,'chapters'=>[$a=>['count'=>1,'marks'=>1]]];
erpEqual(array_column(examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$mcqInput)['questions'],'id'),[$mcq],'MCQ mode excludes all written types');
$bad=$input;$bad['chapters'][$a]['count']=0;erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'All zero counts rejected');
$bad=$input;$bad['chapters'][$a]['marks']='0';erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'Selected chapter needs positive total marks');
$bad=$input;$bad['chapters'][$a]['marks']='5.751';erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'More than two decimals rejected');
$bad=$input;$bad['chapters'][$a]['count']='1.5';erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'Fractional question counts rejected');
$bad=$input;$bad['generation_kind']='all';erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'Unknown question kind rejected');
$bad=$input;$bad['duration_minutes']=1;erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$bad),'Simple mode preserves time limit');
erpReject(fn()=>examGenerateChapterPaper($db,$student,$f['class'],$f['subject'],$input),'Students cannot generate simple papers');
$grid=examChapterGridInput($db,$owner,$f['class'],$f['subject'],$input);
erpReject(fn()=>examSaveGrid($db,$owner,$f['class'],$f['subject'],'Forged type',$grid),'Internal written group cannot be submitted as an advanced grid type');
learningSetArchived($db,$owner,'questions',$mcq,true,'exam');
erpReject(fn()=>examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$mcqInput),'Deleted MCQs cannot be generated');
learningSetArchived($db,$owner,'questions',$mcq,false,'exam');
erpEqual((int)examGenerateChapterPaper($db,$owner,$f['class'],$f['subject'],$mcqInput)['questions'][0]['id'],$mcq,'Restored MCQ retains ID and becomes usable');
echo 'Chapter paper checks passed: '.$GLOBALS['erp_checks'].PHP_EOL;
